<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Maze Discovery</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0; min-height: 100vh; display: grid; place-items: center;
    background: #101522; color: #edf2ff; font: 16px system-ui, sans-serif;
  }
  main { width: min(94vw, 720px); text-align: center; }
  h1 { margin: 0 0 10px; font-size: 1.45rem; }
  .panel {
    display: flex; justify-content: center; align-items: center; gap: 22px;
    margin-bottom: 12px; flex-wrap: wrap;
  }
  .stat { color: #b9c5e4; }
  .stat strong { color: #fff; }
  button {
    border: 0; border-radius: 7px; padding: 8px 15px; cursor: pointer;
    color: #fff; background: #4968d8; font: inherit;
  }
  button:hover { background: #5c7cf0; }
  #maze {
    width: min(94vw, 660px); height: min(94vw, 660px);
    margin: auto; background: #f7f9ff; border-radius: 8px; overflow: hidden;
    box-shadow: 0 10px 32px #0008;
  }
  canvas { display: block; width: 100%; height: 100%; }
  .note { margin: 11px 0 0; color: #9ba9c9; font-size: .82rem; }
</style>
</head>
<body>
<main>
  <h1>Maze Discovery</h1>
  <div class="panel">
    <div class="stat">Found: <strong id="completed">0 / 24</strong></div>
    <div class="stat">Ticks: <strong id="timer">0</strong></div>
    <button id="reset" type="button">New maze</button>
  </div>
  <div id="maze"><canvas aria-label="Exploring maze"></canvas></div>
  <p class="note">Each explorer learns passages only as it reaches them.</p>
</main>

<script>
(() => {
  "use strict";

  const ROWS = 21, COLS = 21, BOT_COUNT = 24, STEP_MS = 145;
  const canvas = document.querySelector("#maze canvas");
  const ctx = canvas.getContext("2d");
  const completedEl = document.getElementById("completed");
  const timerEl = document.getElementById("timer");
  const dirs = [
    { name: "n", dr: -1, dc: 0, opposite: "s" },
    { name: "e", dr: 0, dc: 1, opposite: "w" },
    { name: "s", dr: 1, dc: 0, opposite: "n" },
    { name: "w", dr: 0, dc: -1, opposite: "e" }
  ];

  let grid, lastMoveAt = performance.now(), animationStart = performance.now();
  let rng;

  function seededRandom(seed) {
    let value = (seed >>> 0) || 0x9e3779b9;
    return function () {
      value += 0x6D2B79F5;
      let t = value;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function shuffled(items) {
    const a = items.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(rng() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  function cell(r, c) {
    return { r, c, walls: { n: true, e: true, s: true, w: true } };
  }

  function key(p) { return p.r + "," + p.c; }
  function copyPos(p) { return { r: p.r, c: p.c }; }

  function generateMaze() {
    grid = Array.from({ length: ROWS }, (_, r) =>
      Array.from({ length: COLS }, (_, c) => cell(r, c))
    );
    const seen = new Set(["0,0"]);
    const stack = [{ r: 0, c: 0 }];

    while (stack.length) {
      const here = stack[stack.length - 1];
      const choices = shuffled(dirs).filter(d => {
        const nr = here.r + d.dr, nc = here.c + d.dc;
        return nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS &&
          !seen.has(nr + "," + nc);
      });
      if (!choices.length) {
        stack.pop();
        continue;
      }
      const d = choices[0], next = { r: here.r + d.dr, c: here.c + d.dc };
      grid[here.r][here.c].walls[d.name] = false;
      grid[next.r][next.c].walls[d.opposite] = false;
      seen.add(key(next));
      stack.push(next);
    }
  }

  function makeBot(i, spawn) {
    const order = shuffled(dirs.map(d => d.name));
    const start = copyPos(spawn);
    return {
      id: i,
      color: `hsl(${Math.round(i * 360 / BOT_COUNT)}, 78%, 48%)`,
      order,
      r: start.r, c: start.c,
      from: copyPos(start),
      to: copyPos(start),
      stack: [copyPos(start)],
      visited: new Set([key(start)]),
      known: Object.create(null),
      path: [copyPos(start)],
      deadEnds: [],
      deadSet: new Set(),
      finishTick: null
    };
  }

  function observe(bot) {
    const p = { r: bot.r, c: bot.c };
    bot.known[key(p)] = { ...grid[p.r][p.c].walls };
  }

  function markDead(bot, p) {
    const k = key(p);
    if (!bot.deadSet.has(k)) {
      bot.deadSet.add(k);
      bot.deadEnds.push(copyPos(p));
    }
  }

  function moveBot(bot) {
    if (bot.finishTick !== null) return;
    observe(bot);

    const current = { r: bot.r, c: bot.c };
    const walls = bot.known[key(current)];
    let next = null;

    // This uses only observations stored by this bot at cells it entered.
    for (const name of bot.order) {
      const d = dirs.find(x => x.name === name);
      const candidate = { r: current.r + d.dr, c: current.c + d.dc };
      if (!walls[name] && !bot.visited.has(key(candidate))) {
        next = candidate;
        break;
      }
    }

    if (next) {
      bot.stack.push(copyPos(next));
      bot.visited.add(key(next));
    } else if (bot.stack.length > 1) {
      markDead(bot, current);
      bot.stack.pop();
      next = copyPos(bot.stack[bot.stack.length - 1]);
    } else {
      markDead(bot, current);
      return;
    }

    bot.from = current;
    bot.to = copyPos(next);
    bot.r = next.r;
    bot.c = next.c;
    bot.path.push(copyPos(next));
    observe(bot);

    if (bot.r === game.exit.r && bot.c === game.exit.c) {
      bot.finishTick = game.elapsed;
      bot.from = copyPos(next);
      bot.to = copyPos(next);
    }
  }

  const game = {
    elapsed: 0,
    size: { rows: ROWS, cols: COLS },
    spawn: { r: 0, c: 0 },
    exit: { r: ROWS - 1, c: COLS - 1 },
    bots: [],

    walls(r, c) {
      if (!Number.isInteger(r) || !Number.isInteger(c) ||
          r < 0 || r >= ROWS || c < 0 || c >= COLS) {
        throw new RangeError("Cell is outside the maze");
      }
      return { ...grid[r][c].walls };
    },

    tick(n = 1) {
      n = Math.max(0, Math.floor(Number(n) || 0));
      for (let i = 0; i < n; i++) {
        if (this.bots.every(bot => bot.finishTick !== null)) break;
        this.elapsed++;
        for (const bot of this.bots) moveBot(bot);
      }
      animationStart = performance.now();
      updateStats();
      draw();
    },

    reset(seed) {
      const chosen = typeof seed === "number" && Number.isFinite(seed)
        ? seed
        : Math.floor(Math.random() * 4294967296);
      rng = seededRandom(chosen);
      generateMaze();

      this.elapsed = 0;
      this.spawn = { r: 0, c: 0 };
      // A far corner is always reachable; its location is never supplied to bots.
      this.exit = { r: ROWS - 1, c: COLS - 1 };
      this.bots = Array.from({ length: BOT_COUNT }, (_, i) => makeBot(i, this.spawn));
      for (const bot of this.bots) observe(bot);
      animationStart = performance.now();
      updateStats();
      draw();
    }
  };

  window.game = game;

  function updateStats() {
    const done = game.bots.filter(b => b.finishTick !== null).length;
    completedEl.textContent = `${done} / ${BOT_COUNT}`;
    timerEl.textContent = game.elapsed;
  }

  function resizeCanvas() {
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.round(rect.width * dpr);
    canvas.height = Math.round(rect.height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    draw();
  }

  function draw() {
    if (!grid) return;
    const width = canvas.getBoundingClientRect().width;
    const height = canvas.getBoundingClientRect().height;
    const cw = width / COLS, ch = height / ROWS;
    const wall = Math.max(2, Math.min(cw, ch) * .105);

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = "#f7f9ff";
    ctx.fillRect(0, 0, width, height);

    ctx.fillStyle = "#d8f4df";
    ctx.fillRect(game.exit.c * cw + wall, game.exit.r * ch + wall, cw - 2 * wall, ch - 2 * wall);
    ctx.fillStyle = "#ffe0a8";
    ctx.fillRect(game.spawn.c * cw + wall, game.spawn.r * ch + wall, cw - 2 * wall, ch - 2 * wall);

    ctx.strokeStyle = "#192238";
    ctx.lineWidth = wall;
    ctx.lineCap = "square";
    ctx.beginPath();
    for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
      const w = grid[r][c].walls, x = c * cw, y = r * ch;
      if (w.n) { ctx.moveTo(x, y); ctx.lineTo(x + cw, y); }
      if (w.w) { ctx.moveTo(x, y); ctx.lineTo(x, y + ch); }
      if (r === ROWS - 1 && w.s) { ctx.moveTo(x, y + ch); ctx.lineTo(x + cw, y + ch); }
      if (c === COLS - 1 && w.e) { ctx.moveTo(x + cw, y); ctx.lineTo(x + cw, y + ch); }
    }
    ctx.stroke();

    const complete = game.bots.every(b => b.finishTick !== null);
    const t = complete ? 1 : Math.min(1, (performance.now() - animationStart) / STEP_MS);
    for (const bot of game.bots) {
      const rr = bot.from.r + (bot.to.r - bot.from.r) * t;
      const cc = bot.from.c + (bot.to.c - bot.from.c) * t;
      ctx.beginPath();
      ctx.arc((cc + .5) * cw, (rr + .5) * ch, Math.max(3, Math.min(cw, ch) * .18), 0, Math.PI * 2);
      ctx.fillStyle = bot.color;
      ctx.fill();
      ctx.strokeStyle = "#fff";
      ctx.lineWidth = 1.2;
      ctx.stroke();
    }
  }

  document.getElementById("reset").addEventListener("click", () => game.reset());
  window.addEventListener("resize", resizeCanvas);

  game.reset(123456789);
  resizeCanvas();

  setInterval(() => {
    if (!game.bots.every(bot => bot.finishTick !== null)) game.tick(1);
  }, STEP_MS);

  function frame() {
    draw();
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
